<?php declare(strict_types=1); ?>
<div class="ap-grid"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Payment calendar</span><h2>Invoice schedules</h2></div><span class="panel-meta"><?= count($schedules) ?> records</span></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Schedule</th><th>Invoice</th><th>Supplier</th><th>Date</th><th>Method</th><th>Status</th><th class="numeric">Net</th></tr></thead><tbody><?php foreach($schedules as$s): $i=fulfillment_find_invoice((int)$s['invoice_id']); ?><tr><td><strong><?= h($s['schedule_number']) ?></strong></td><td><?= h($i['invoice_number']??'Unavailable') ?></td><td><?= h(data_supplier_name($s['supplier_id'])) ?></td><td><?= h(date_us($s['scheduled_date'])) ?></td><td><?= h(status_label($s['payment_method'])) ?></td><td><?= badge($s['status']) ?></td><td class="numeric"><?= money($s['net_amount']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<aside class="panel"><header class="panel-head"><div><span class="eyebrow">Approved invoice</span><h2>Create payment schedule</h2></div></header><form class="ap-form" method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="schedule_invoice"><label class="span-2"><span>Invoice</span><select name="invoice_id" required><?php foreach(accounts_payable_eligible_invoices() as$i): if(fulfillment_invoice_effective_status($i)!=='approved_for_payment')continue; ?><option value="<?= (int)$i['id'] ?>"><?= h($i['invoice_number'].' · '.data_supplier_name($i['supplier_id']).' · '.money($i['total_amount'])) ?></option><?php endforeach; ?></select></label><label><span>Scheduled date</span><input type="date" name="scheduled_date" value="<?= date('Y-m-d',strtotime('+3 days')) ?>" required></label><label><span>Method</span><select name="payment_method"><?php foreach(accounts_payable_payment_methods()as$m): ?><option value="<?= h($m) ?>"><?= h(status_label($m)) ?></option><?php endforeach; ?></select></label><label><span>Owner</span><select name="owner_id"><?= user_options($owner) ?></select></label><label><span>Reviewer</span><select name="reviewer_id"><?= user_options($reviewer) ?></select></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required>Invoice is three-way matched, approved for payment, and scheduled according to supplier terms and cash requirements.</textarea></label><?php if(can('accounts_payable.create')): ?><button class="button primary span-2">Create schedule</button><?php endif; ?></form></aside></div>
